from rdkit.Chem.rdchem import ChiralType
from rdkit.Chem.rdmolops import FindAtomEnvironmentOfRadiusN

def rooted_sub(mol, root, radius):
    ids = FindAtomEnvironmentOfRadiusN(mol=mol, radius=radius, rootedAtAtom=root)
    am = {}; s = PathToSubmol(mol, ids, atomMap=am)
    root_in_sub = am[root]
    return s, root_in_sub

def canon_clear_all(sub, r):
    rw = RWMol(sub)
    for a in rw.GetAtoms(): a.SetChiralTag(ChiralType.CHI_UNSPECIFIED)
    return MolToSmiles(rw.GetMol(), rootedAtAtom=r, isomericSmiles=True)

def canon_keep_root(sub, r):
    rw = RWMol(sub)
    for a in rw.GetAtoms():
        if a.GetIdx()!=r: a.SetChiralTag(ChiralType.CHI_UNSPECIFIED)
    return MolToSmiles(rw.GetMol(), rootedAtAtom=r, isomericSmiles=True)

