        folded[hashed % self.fp_size] = 1
    return folded

def _minhash_sketch(self, shingle_counts: dict[str, int]) -> np.ndarray:
    # MinHash sketch of the set of shingles: each of the fp_size sketch
    # coordinates is the minimum, over all shingles, of a distinct random
    # permutation h_i(x) = (a_i * x + b_i) mod 2**64 (a_i odd), a family
    # with zero collision probability for distinct shingles, which makes
    # the fraction of equal sketch coordinates between two molecules an
    # unbiased estimator of their Jaccard similarity. The permutations are
    # drawn deterministically from random_state, so sketches of different
    # molecules are comparable.
    seed = check_random_state(self.random_state)
    uint64_max = np.iinfo(np.uint64).max
    a = seed.randint(2, uint64_max + 1, size=self.fp_size, dtype=np.uint64) | 1
    b = seed.randint(0, uint64_max + 1, size=self.fp_size, dtype=np.uint64)

    sketch = np.full(self.fp_size, uint64_max, dtype=np.uint64)
    for shingle in self._final_shingles(shingle_counts):
        hashed = struct.unpack("<Q", sha256(shingle).digest()[:8])[0]
        sketch = np.minimum(sketch, a * hashed + b)
    return sketch

def _final_shingles(self, shingle_counts: dict[str, int]) -> list[bytes]:
    if self.include_duplicated_shingles:
        return [
            f"{shingle}|{count}".encode("utf-8")
            for shingle, count in sorted(shingle_counts.items())
        ]
    return [shingle.encode("utf-8") for shingle in sorted(shingle_counts)]
